/**
 * Source-derived question bank: every record of docs/sources/apohenia/Impact_Question_Bank.md
 * as data. Generated from the markdown by a one-off parser and checked in; the template and
 * purpose text is the bank's editorially normalized wording, not a verbatim transcript quote.
 *
 * Use classes (from the bank's own header):
 * - adapt: a question objective that may be adapted into an approved live track.
 * - study_only: preserved for study, never entered into a live prompt or hint.
 * - private_training: self-directed practice and reflection for the rep, never prospect-facing.
 *
 * The raw source excerpts are deliberately not included here. They live in the source file.
 * Pure data: no React, no fetch, no clock.
 */

export type QuestionUse = "adapt" | "study_only" | "private_training";

export type QuestionPhase =
  | "intent"
  | "logicalCertainty"
  | "setterTransition"
  | "emotionalCertainty"
  | "pitch"
  | "mirror"
  | "objection"
  | "identityAndTaxonomy"
  | "training"
  | "followUp"
  | "referral"
  | "upsellSetting"
  | "upsellClosing"
  | "reviewedCall";

export interface QuestionRecord {
  /** Bank id, e.g. "L06". The letter is the bank's own series; the phase is derived from it. */
  id: string;
  phase: QuestionPhase;
  label: string;
  /** Editorially normalized template. Bracketed parts are slots the seller fills from the conversation. */
  template: string;
  /** The instructor's intended purpose, as the bank states it. */
  purpose: string;
  /** Delivery described in the source text. Described, not measured from audio. */
  delivery: string;
  use: QuestionUse;
  /** Source file, section and original character range, as the bank cites it. */
  sourceRef: string;
}

