/** Records the model and the UI may draw on for live hints and angles. Only `adapt`. */
export const LIVE_QUESTIONS: readonly QuestionRecord[] = QUESTION_BANK.filter((r) => r.use === "adapt");

/** Records kept for study of the source method. Never enter a live prompt. */
export const STUDY_ONLY: readonly QuestionRecord[] = QUESTION_BANK.filter((r) => r.use === "study_only");

/** Records for the rep's own practice and reflection. Never prospect-facing. */
export const PRIVATE_TRAINING: readonly QuestionRecord[] = QUESTION_BANK.filter((r) => r.use === "private_training");

export interface BankCounts {
  total: number;
  adapt: number;
  study_only: number;
  private_training: number;
  byPhase: Record<QuestionPhase, number>;
}

function countBank(): BankCounts {
  const byPhase = {} as Record<QuestionPhase, number>;
  let adapt = 0;
  let study_only = 0;
  let private_training = 0;
  for (const r of QUESTION_BANK) {
    byPhase[r.phase] = (byPhase[r.phase] ?? 0) + 1;
    if (r.use === "adapt") adapt += 1;
    else if (r.use === "study_only") study_only += 1;
    else private_training += 1;
  }
  return { total: QUESTION_BANK.length, adapt, study_only, private_training, byPhase };
}

/** Counted from the data, not typed by hand. The source header claims 207 records. */
export const BANK_COUNTS: BankCounts = countBank();

/** The bank's own record count claim, kept beside the parsed count so a drift is visible. */
export const BANK_CLAIMED_TOTAL = 207;

/** All records for a phase, in bank order. Pass `liveOnly` to drop study_only and private_training. */
export function byPhase(phase: QuestionPhase, liveOnly = false): QuestionRecord[] {
  return QUESTION_BANK.filter((r) => r.phase === phase && (!liveOnly || r.use === "adapt"));
}

export function questionById(id: string): QuestionRecord | undefined {
  return QUESTION_BANK.find((r) => r.id === id);
}
